import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Wallet, type LedgerEntry, type SubmittableTransaction } from 'xrpl';
import { amount, MptIssuer, MAX_AMOUNT, REQUIRED_FLAGS } from '../src/issuer.js';
import type { LedgerPort, Receipt } from '../src/ledger.js';
import type { BanStore } from '../src/storage.js';

const issuerAddress = Wallet.generate().classicAddress;
const holder = Wallet.generate().classicAddress;
const id = 'A'.repeat(48);
function fixture() {
  const calls: SubmittableTransaction[] = [];
  let balance = '200', flags = 2, failDrain = false;
  const banned = new Set<string>();
  const bans: BanStore = { has: async (i, h) => banned.has(`${i}:${h}`), add: async (i, h) => { banned.add(`${i}:${h}`); } };
  const ledger: LedgerPort = {
    issuance: async () => ({ Issuer: issuerAddress, Flags: REQUIRED_FLAGS, AssetScale: 0 }) as LedgerEntry.MPTokenIssuance,
    holding: async () => ({ MPTAmount: balance, Flags: flags }) as LedgerEntry.MPToken,
    send: async (_key, tx) => {
      calls.push(tx);
      if (tx.TransactionType === 'MPTokenAuthorize') flags = tx.Flags === 1 ? 0 : 2;
      if (tx.TransactionType === 'Clawback') {
        if (failDrain) throw new Error('Network unavailable');
        balance = '0';
      }
      return { hash: 'test', ledgerIndex: 1, code: 'tesSUCCESS', meta: { TransactionResult: 'tesSUCCESS', AffectedNodes: [], TransactionIndex: 0 } } as Receipt;
    },
  };
  return { issuer: new MptIssuer(issuerAddress, id, ledger, bans), ledger, bans, calls, fail: (value: boolean) => { failDrain = value; } };
}
