  for (const value of ['0', '-1', '1.5', '01', '1e3', ' 1', (BigInt(MAX_AMOUNT) + 1n).toString()]) assert.throws(() => amount(value));
  assert.equal(amount(MAX_AMOUNT), MAX_AMOUNT);
  assert.equal(amount('9007199254740993'), '9007199254740993');
